#include <iostream>

bool isLowerVowel(char c)
{
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
}

int checkVowel(char input, bool expected)
{
    return isLowerVowel(input) == expected ? 0 : 1;
}

int testVowel()
{
    if (checkVowel('a', true) != 0) return 1;
    if (checkVowel('q', false) != 0) return 2;
    return 0;
}

int main()
{
    const int failedCase{testVowel()};
    if (failedCase == 0) std::cout << "Vowel checks passed\n";
    else std::cout << "Failed vowel case " << failedCase << '\n';
    return 0;
}

practice.tests:
#define main learner_main
#include "main.cpp"
#undef main
#include <iostream>

int main()
{
    int failures{};
    const char inputs[]{'a', 'e', 'i', 'o', 'u', 'b', 'q', 'y', 'z', 'A', 'E', 'I', 'O', 'U', '0', ' ', '\n', '\0'};
    const bool expected[]{true, true, true, true, true, false, false, false, false, false, false, false, false, false, false, false, false, false};
    for (unsigned i{}; i < sizeof(inputs) / sizeof(inputs[0]); ++i)
    {
        if (isLowerVowel(inputs[i]) != expected[i])
        {
            std::cerr << "Wrong classification at case " << i << '\n';
            ++failures;
        }
        if (checkVowel(inputs[i], expected[i]) != 0)
        {
            std::cerr << "Matching expectation rejected at case " << i << '\n';
            ++failures;
        }
        if (checkVowel(inputs[i], !expected[i]) != 1)
        {
            std::cerr << "Mismatching expectation not reported at case " << i << '\n';
            ++failures;
        }
    }
    if (testVowel() != 0)
    {
        std::cerr << "Retained smoke checks should pass for the correct predicate\n";
        ++failures;
    }
    return failures == 0 ? 0 : 1;
}

